<?php namespace App\Http\Controllers; use App\Models\{Invoice,Job,Customer,Vehicle,Product}; use Illuminate\Support\Facades\DB;
class ReportController extends Controller {public function index(){return view('reports.index',['revenue'=>Invoice::sum('total'),'paid'=>Invoice::sum('paid'),'outstanding'=>Invoice::sum('balance'),'jobs'=>Job::count(),'customers'=>Customer::count(),'vehicles'=>Vehicle::count(),'stockValue'=>DB::table('inventory')->join('products','products.id','=','inventory.product_id')->selectRaw('COALESCE(SUM(inventory.quantity*products.cost_price),0) v')->value('v')]);}}
